import { words, groupBy } from 'es-toolkit';
import { isEmpty } from 'es-toolkit/compat';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

export function tokens(text: string): string[] {
  return words(text);
}

export function byAge(rows: Row[]): Record<string, Row[]> {
  return groupBy(rows, (row) => row.age);
}

export function isBlank(value: unknown): boolean {
  return isEmpty(value);
}
EOF
npm run size -- out/module.ts 2>&1 | tail -2
cat > t.mjs <<'EOF'
import * as m from 'es-toolkit';
import * as c from 'es-toolkit/compat';
for (const v of [null,true,0,5,-5,"","a",[],[1],{},{a:1},[[]],{a:{}}]) console.log(JSON.stringify(v),c.isEmpty(v));
const r=[{id:1,age:30},{id:2,age:20},{id:3,age:30}];
console.log(JSON.stringify(m.groupBy(r,x=>x.age)),JSON.stringify(c.groupBy(r,'age')),JSON.stringify(m.groupBy([],x=>x.age)));
EOF
